#include <iostream>
#include <vector>
using namespace std;

// 深度优先搜索枚举运算符
bool dfsOps(const vector<int>& perm, int pos, int cur) {
    int n = perm.size();
    if (pos == n) {
        return cur == 24;
    }
    int x = perm[pos];
    // 依次尝试 +, -, *, /
    if (dfsOps(perm, pos + 1, cur + x)) return true;
    if (dfsOps(perm, pos + 1, cur - x)) return true;
    if (dfsOps(perm, pos + 1, cur * x)) return true;
    // C++ 整数除法对int是向零取整
    if (dfsOps(perm, pos + 1, cur / x)) return true;
    return false;
}

// 深度优先搜索枚举排列
bool dfsPerm(const vector<int>& nums, vector<bool>& used, vector<int>& perm, int idx) {
    int n = nums.size();
    if (idx == n) {
        return dfsOps(perm, 1, perm[0]);
    }
    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            used[i] = true;
            perm[idx] = nums[i];
            if (dfsPerm(nums, used, perm, idx + 1)) {
                return true;
            }
            used[i] = false;
        }
    }
    return false;
}

// 判断是否能合成24
bool canMake24(const vector<int>& nums) {
    int n = nums.size();
    vector<bool> used(n, false);
    vector<int> perm(n);
    return dfsPerm(nums, used, perm, 0);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<int> nums(n);
        for (int i = 0; i < n; i++) {
            cin >> nums[i];
        }
        cout << (canMake24(nums) ? "Yes" : "No") << "\n";
    }
    return 0;
}
